} from "./stagePolicy.js";
import { redactSecretsText } from "../../shared/redactSecrets.js";
import { buildBelowMinimumRefusal } from "./runnerVersionCompat.js";
import { servingModelFor } from "./runnerPosture.js";
import {
	buildTimelineAttribution,
	stampArrivalRowAttribution,
} from "./runAttribution.js";

/***
 * MARK: resolveCiTimeoutMs
 * @description CI budget for one dispatched stage, in milliseconds. Honors
 *   the stage's explicit `timeoutMs`, then the legacy `timeout` field the
 *   project file actually carries, then the project default, then the
 *   10-minute floor. The `timeout` fallback matters: without it the
 *   Automated-tests stage's configured 3600000ms never reached the runner
 *   and every gate longer than 10 minutes was SIGKILLed mid-run (task
 *   b5716327: green suites reported as "exit code 1").
 * @example resolveCiTimeoutMs({ timeout: 3600000 }, {}) => 3600000
 * @param {Object} [resolved] - resolved CI stage definition.
 * @param {Object} [project] - project record (optional `ciTimeoutMs`).
 * @returns {number} Effective CI timeout in milliseconds.
 ***/
export const resolveCiTimeoutMs = (resolved, project) => {
	return (
		Number(resolved?.timeoutMs) ||
		Number(resolved?.timeout) ||
		Number(project?.ciTimeoutMs) ||
		600000
	);
};

/***
 * MARK: stampDispatchRunAttribution
 * @description Stamps one dispatched run's resolved choice onto the task —
 *   the runner-side mirror of the embedded dispatch stamp in
 *   `executeStage`, so timeline rows and reports attribute the model that
 *   was ACTUALLY matched, never a fallback. The requirement's harness/
 *   model name the run (model normalized through `servingModelFor`, so the
 *   "default" sentinel and non-LLM kinds never stamp); a resolved alias
 *   rides along with its name and target index. The dispatching Runner's
 *   `runnerId` rides along too, so a struggling Runner can be spotted per
 *   stage or task type later — CI/merge requirements carry no
 *   harness/model, but a Runner-run CI/merge row still stamps the Runner
 *   itself (never a model: a scripted stage must never show one).
 *   Best-effort: a stamping failure never blocks the claim.
 * @example stampDispatchRunAttribution({ taskStore, project, task, stage, stages, req: { harness: 'pi', model: 'm', kind: 'agent' }, runnerId: 'runner-alpha' })
 * @param {Object} args - `{ taskStore, project, task, stage, stages, req, runnerId }`.
 * @returns {Object|null} The stamped attribution, or null when nothing ran behind the dispatch.
 ***/
export function stampDispatchRunAttribution({ taskStore, project, task, stage, stages, req, runnerId = null }) {
	try {
		if (!task || !req) return null;
		const resolvedAlias =
			req.alias && typeof req.alias === "object" && typeof req.alias.name === "string"
				? req.alias
				: null;
		const attribution = buildTimelineAttribution({
			harnessId: typeof req.harness === "string" && req.harness.trim() ? req.harness.trim() : null,
			modelRef: servingModelFor({ kind: req.kind, model: req.model }),
			aliasName: resolvedAlias ? resolvedAlias.name : null,
			targetIndex: resolvedAlias ? resolvedAlias.targetIndex : null,
			runnerId,
		});
		if (!attribution) return null;
		task.currentRunAttribution = {
			stageId: stage?.id ?? task.currentStageId ?? null,
			...attribution,
		};
		const arrivalLabel =
			stage?.name || resolveStageLabel(stage?.id ?? task.currentStageId, stages || []);
		const stampedRow = stampArrivalRowAttribution(task, arrivalLabel, attribution);
		if (stampedRow) {
			try {
				taskStore?._saveTaskMarkdown?.(project?.cwd, task);
			} catch {
				// Persisting the stamp is best-effort; the in-memory
				// attribution already drives the completion row.
			}
		}
		return attribution;
	} catch {
		return null;
	}
}

/***
 * MARK: prepareIntegrationAttempt
 * @description Backend-side preparation for one leased `integrate` dispatch
 *   (Step 4): fetches the origin (read-only — the backend never pushes),
 *   reads the remote task-branch and target-branch tips as the attempt's
 *   expected SHAs, and pins a stable `mergeAttemptId` on the task so every
 *   dispatch poll for this merge reuses one queue entry (idempotent
 *   re-enqueue) instead of queueing a duplicate merge per poll. Throws
 *   `INTEGRATION_UNPREPARED` when the refs cannot be read (no origin ref
 *   yet, fetch failure) — the task stays `in_stage` for the next poll.
 * @example await prepareIntegrationAttempt({ taskStore, projectStore, projectId: 'p', task }) => { targetBranch: 'main', ... }
 * @param {Object} args - `{ taskStore, projectStore, projectId, task }`.
 * @returns {Promise<Object>} `{ targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId }`.
 ***/
export const prepareIntegrationAttempt = async ({ taskStore, projectStore, projectId, task }) => {
	const unprepared = (detail) => {
		const err = new Error(`Integration attempt unprepared: ${detail}`);
		err.code = "INTEGRATION_UNPREPARED";
		throw err;
	};
	const project = projectStore?.getProject?.(projectId);
	const cwd = project?.cwd;
	if (!cwd) unprepared("project has no checkout");
	const taskBranch = taskStore.resolveTaskBranch(task);
	let targetBranch;
	try {
		targetBranch = await defaultBranch(cwd);
	} catch {
		unprepared("cannot resolve the target branch");
	}
	try {
		// Prune: a deleted remote task branch must vanish from the
		// remote-tracking refs too, or a later attempt would merge a
		// resurrected stale tip.
		await git(cwd, ["fetch", "--prune", "origin"], { timeout: 60000 });
	} catch (e) {
		unprepared(`fetch failed (${e?.message || e})`);
	}
	const readRef = async (ref) => {
		try {
			return (await git(cwd, ["rev-parse", "--verify", ref])).stdout.trim() || null;
		} catch {
			return null;
		}
	};
	const expectedTargetSha = await readRef(`origin/${targetBranch}`);
	const expectedTaskSha = await readRef(`origin/${taskBranch}`);
	if (!expectedTargetSha) unprepared(`remote ref 'origin/${targetBranch}' does not exist`);
	if (!expectedTaskSha) unprepared(`remote ref 'origin/${taskBranch}' does not exist (task work not pushed yet)`);
	// A retry after a failed attempt gets a FRESH attempt id: the failed
	// lease settled terminal (landed/conflict/stale-head/failed) in the
	// integration queue, and re-enqueueing the same id would collide with
	// that settled entry instead of queueing a re-based merge.
	const failedBefore = !!(task.lastError && (task.lastError.message || task.lastError.reason || task.lastError.stageId || task.lastError.stderr));
	let mergeAttemptId = `merge-${String(task.id).slice(0, 8)}-${Date.now()}`;
	if (typeof task.mergeAttemptId === "string" && task.mergeAttemptId.trim() && !failedBefore) {
		mergeAttemptId = task.mergeAttemptId.trim();
	} else {
		taskStore.updateTask(projectId, task.id, { mergeAttemptId }, cwd);
		task.mergeAttemptId = mergeAttemptId;
	}
	return { targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId };
};

/***
 * MARK: registerRunnerRoutes
 * @description Runner-facing endpoints (ADR 0009 lifecycle steps 1–6): join
 *   registration, heartbeat, the operator approve/deny/revoke/pause/resume
 *   + list surface the Phase 2 onboarding UI drives, the atomic task-claim
 *   route backed by ClaimStore (200 + lease or 409 + holder), and the
 *   execution-report endpoints (progress, logs, complete-execution with
 *   engine-owned finish, interrupt, monitor). Credential
 *   scope is enforced per request: the claim's Runner always comes from
 *   the authenticated credential, never from the body (R04 wrong-scope).
 * @example await app.register(runnerRoutes, { deps })
 ***/
export const registerRunnerRoutes = async (app, { deps }) => {
	const {
		runnerRegistry,
		claimStore,
		steerStore,
		executionLedger,
		integrationQueue,
		taskStore,
		projectStore,
		resolveAndGuardProject,
		eventBridge,
	} = deps;

	const sendStoreError = (reply, err) => {
		const status = err.statusCode || 500;
		const body = { error: err.message || "Internal error" };
		if (err.code) body.code = err.code;
		if (err.holder) body.holder = err.holder;
		return reply.status(status).send(body);
	};

	const ciPayloadFor = async (projectId, task, stage) => {
		const project = projectStore.getProject(projectId);
		const stages = resolveStagesForTask(project, task);
		// A null/undefined stage (e.g. the single-assignment claim route) falls
		// back to the task's current stage — dropping the payload here would
		// silently strip kind/command/runOnBranch and the Runner would run the
		// command in the task worktree regardless of the stage's branch mode.
		const resolved = stage || stages.find((x) => String(x?.id) === String(task?.currentStageId)) || stages[0];
		if (!resolved) return {};
		const type = String(resolved.type || "").toLowerCase();
		if (!["ci", "script", "deploy", "command"].includes(type)) return {};
		// Branch mode rides every payload — including the error fallback — so a
		// Runner can never silently degrade a 'primary'/'custom' stage back to
		// the task worktree (which is exactly how publish stages used to fail:
		// deploy.sh refuses to run from a kb/* worktree).
		const runOnBranch = typeof resolved.runOnBranch === "string" ? resolved.runOnBranch : "task";
		const branchPayload = {
			runOnBranch,
			...(runOnBranch === "custom" && typeof resolved.customBranch === "string" && resolved.customBranch.trim()
				? { customBranch: resolved.customBranch.trim() }
				: {}),
		};
		// Generic lifecycle seam (mirrors runCommandStage): every command
		// stage announces entry the same way, whether a Runner or the
		// backend executes it. Installed continuity plugins may record
		// entry markers and contribute child-process environment here;
		// with no plugins this is an empty bag. Never throws: a plugin
		// failure must not break dispatch.
		let lifecycleEnv = {};
		try {
			const lifecycle = await emitStageLifecycle("stage:enter", {
				store: taskStore,
				projectId,
				taskId: task?.id,
				stage: resolved,
				kind: "ci",
				cwd: project?.cwd || "",
			});
			if (lifecycle && typeof lifecycle.env === "object") {
				lifecycleEnv = lifecycle.env;
			}
		} catch {
			lifecycleEnv = {};
		}
		try {
			const ctx = buildCommandKeywordContext({ task, stage: resolved, project, projectCwd: project?.cwd || "" });
			return {
				kind: "ci",
				command: expandStageCommand(resolved.command || resolved.script || "echo 'CI stage completed'", ctx),
				timeoutMs: resolveCiTimeoutMs(resolved, project),
				...branchPayload,
				env: lifecycleEnv,
			};
		} catch { return { kind: "ci", command: resolved.command || resolved.script || "", timeoutMs: 600000, ...branchPayload, env: lifecycleEnv }; }
	};

	const authedRunner = (request) => {
		const credential = String(
			request.headers?.["x-runner-credential"] || "",
		).trim();
		return runnerRegistry.authenticate(credential);
	};

	app.post("/runners/register", async (request, reply) => {
		try {
			const result = runnerRegistry.register({
				runnerId: request.body?.runnerId,
				joinToken: request.body?.joinToken,
				facts: request.body?.facts || {},
			});
			return reply.status(result.status === "pending" ? 202 : 200).send(result);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/heartbeat", async (request, reply) => {
		try {
			const runner = authedRunner(request);
			const result = runnerRegistry.heartbeat({
				runnerId: request.body?.runnerId || runner.runnerId,
				credential: String(
					request.headers?.["x-runner-credential"] || "",
				).trim(),
				facts: request.body?.facts || {},
				// G11 audit alert: one identity from multiple origins.
				origin: request.ip || null,
			});
			// D5 pull channel (ADR 0011): pending steers for this
			// Runner's live executions ride the heartbeat response, so
			// steering needs no second channel. Stale Runner, live
			// lease: the steer waits here until the TTL lapses.
			const pendingSteers = [];
			for (const hold of claimStore.liveHolds()) {
				if (hold.runnerId !== runner.runnerId) continue;
				for (const steer of steerStore.pendingFor(hold.executionId)) {
					pendingSteers.push({
						steerId: steer.steerId,
						taskId: hold.taskId,
						projectId: hold.projectId,
						executionId: hold.executionId,
						epoch: hold.epoch,
						text: steer.text,
					});
				}
			}
			return { ...result, pendingSteers };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners", async () => {
		return runnerRegistry.list();
	});

	app.post("/runners/:id/approve", async (request, reply) => {
		try {
			return runnerRegistry.approve(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/rotate", async (request, reply) => {
		try {
			return runnerRegistry.rotate(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/deny", async (request, reply) => {
		try {
			return runnerRegistry.deny(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/revoke", async (request, reply) => {
		try {
			return runnerRegistry.revoke(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/pause", async (request, reply) => {
		try {
			return runnerRegistry.pause(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/resume", async (request, reply) => {
		try {
			return runnerRegistry.resume(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners/:id/config", async (request, reply) => {
		// Operator-owned Runner configuration for the System Settings
		// Runner screen (display name, tool filter, job-type switches,
		// directories, project override). No Runner credential needed:
		// same operator surface as approve/deny/pause/resume.
		try {
			return runnerRegistry.getConfig(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.patch("/runners/:id/config", async (request, reply) => {
		try {
			return runnerRegistry.updateConfig(request.params.id, request.body || {});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/skip", async (request, reply) => {
		// Operator skip: advance the task this Runner currently holds past
		// its stage and release the lease, so the in-flight Runner report
		// lands stale (stage-moved) instead of re-advancing. Same operator
		// surface as pause/resume — no Runner credential needed. 404 when
		// the Runner is unknown or holds nothing; 409 when its task is
		// already on the last stage.
		try {
			const runnerId = request.params.id;
			const record = runnerRegistry
				.records()
				.find((r) => r && r.runnerId === runnerId);
			if (!record) {
				return reply
					.status(404)
					.send({ error: `Unknown Runner ${runnerId}.`, code: "UNKNOWN_RUNNER" });
			}
			const hold = claimStore
				.liveHolds()
				.find((h) => h && h.runnerId === runnerId);
			if (!hold) {
				return reply.status(404).send({
					error: `Runner ${runnerId} has no active task to skip.`,
					code: "NOTHING_TO_SKIP",
				});
			}
			const project = projectStore.getProject(hold.projectId);
			const task = taskStore.getTask(hold.projectId, hold.taskId);
			if (!task) {
				claimStore.invalidate(hold.taskId);
				return reply.status(404).send({
					error: "Held task not found.",
					code: "NOTHING_TO_SKIP",
				});
			}
			const stages = Array.isArray(project?.stages) ? project.stages : [];
			const index = stages.findIndex((s) => s && s.id === task.currentStageId);
			if (index === -1 || index >= stages.length - 1) {
				return reply.status(409).send({
					error: `Task ${hold.taskId} is already on the last stage.`,
					code: "NOTHING_TO_SKIP",
				});
			}
			const next = stages[index + 1];
			taskStore.updateTask(
				hold.projectId,
				hold.taskId,
				{ currentStageId: next.id },
				project?.cwd,
			);
			claimStore.invalidate(hold.taskId);
			return {
				success: true,
				runnerId,
				taskId: hold.taskId,
				from: task.currentStageId,
				to: next.id,
			};
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	const guardedTask = (request, reply) => {
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return null;
		const task = taskStore.getTask(projectId, request.params.id);
		if (!task) {
			reply.status(404).send({ error: "Task not found" });
			return null;
		}
		return { projectId, task };
	};

	app.get("/runners/monitor", async () => {
		// Multi-Runner UI (WP-3.4): who runs what right now, so
		// Settings › Runners can show live assignments.
		// `scheduler` exposes the cutover deferral counters so a task
		// sitting in_stage is diagnosable: a climbing `deferredDispatch`
		// with no Runner pickup means the fleet is empty or mismatched.
		const liveAssignments = claimStore.liveHolds().map((hold) => {
			const record = runnerRegistry.records().find((r) => r.runnerId === hold.runnerId) || null;
			return {
				runnerId: hold.runnerId,
				projectId: hold.projectId,
				taskId: hold.taskId,
				executionId: hold.executionId,
				epoch: hold.epoch,
				startedAt: hold.startedAt ?? null,
				stageId: executionLedger.stageFor(hold.executionId),
				prompt: executionLedger.promptFor(hold.executionId),
				serving: executionLedger.servingFor(hold.executionId),
				lastSeenAt: record?.lastSeenAt ?? null,
			};
		});
		const sched = taskStore.schedulerStats || {};
		const scheduler = {
			ticks: sched.ticks || 0,
			dispatched: sched.dispatched || 0,
			deferredDispatch: sched.deferredDispatch || 0,
			deferredTripped: sched.deferredTripped || 0,
			lastOutcome: sched.lastOutcome ?? null,
			lastDispatchAt: sched.lastDispatchAt ?? null,
		};
		// Step 6: surface integration-queue health (depth/lease per scope
		// via GET /runners/integration; global lease counters here) so a
		// stuck merge queue is visible before tasks pile up behind it.
		const integration = integrationQueue ? integrationQueue.snapshot() : {};
		return { ...executionLedger.snapshot(), liveAssignments, scheduler, integration };
	});

	app.get("/runners/models/catalogue", async () => {
		// Fleet model catalogue: derived live from Runner registrations
		// (never cached), so joins, leaves, heartbeat updates, and
		// operator allowlist edits reflect on the next read. One entry
		// per distinct model id served by at least one claim-eligible
		// Runner (active, not paused), with the serving harness ids,
		// tiers, and runner count/ids. Stage, default, and alias pickers
		// read this for availability instead of credential health.
		return buildFleetModelCatalog(runnerRegistry.list());
	});

	app.post("/tasks/:id/progress", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.recordProgress({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				stageId: request.body?.stageId,
				event: request.body?.event,
				prompt: request.body?.prompt ?? null,
				harness: request.body?.harness ?? null,
				model: request.body?.model ?? null,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/logs", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = executionLedger.ingestLogs({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				seq: request.body?.seq,
				bytes: request.body?.bytes,
			});
			// Live turn-by-turn stream: fan the ingested frame out over the
			// socket so the Logs tab shows Runner output as it happens, not
			// only after the next task refetch. Fire-and-forget: a dead
			// socket must never fail the ingest. Duplicates are suppressed
			// once the stored entry arrives (client dedupes on
			// executionId+seq), and duplicate/old frames are never emitted.
			// The broadcast is redacted even though the stored copy already
			// is: legacy text frames reach this route unredacted from older
			// Runners (the fallback text path), and the live socket must
			// never carry secrets even for one frame.
			if (!receipt.duplicate) {
				eventBridge
					?.emitProcessEvent(ctx.projectId, "process:stdout", {
						taskId: request.params.id,
						projectId: ctx.projectId,
						chunk: `[runner ${runner.runnerId}] ${redactSecretsText(String(request.body?.bytes ?? ""))}`,
						tag: "[RUNNER]",
						runnerId: runner.runnerId,
						executionId: request.body?.executionId,
						seq: request.body?.seq,
					})
					?.catch?.(() => {});
			}
			return receipt;
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/log-events", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = executionLedger.ingestLogEvents({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				seq: request.body?.seq,
				events: request.body?.events,
			});
			// Live structured stream: fan the ingested entries out over the
			// socket so the Logs tab renders tool calls, results, thinking,
			// errors, and telemetry as they happen — the same records a
			// later refetch persists. Only the entries appended by THIS
			// batch ship (re-read from the stored tail, which the ledger
			// just extended). Fire-and-forget; duplicates never emit.
			if (!receipt.duplicate) {
				const task = taskStore.getTask(ctx.projectId, request.params.id);
				const stored = Array.isArray(task?.logEntries) ? task.logEntries : [];
				const fresh = stored
					.filter(
						(entry) =>
							entry?.meta?.executionId === request.body?.executionId &&
							entry?.meta?.seq === request.body?.seq &&
							entry?.meta?.source === "runner-structured",
					)
					.slice(-200);
				eventBridge
					?.emitProcessEvent(ctx.projectId, "process:log-entries", {
						taskId: request.params.id,
						projectId: ctx.projectId,
						entries: fresh,
						runnerId: runner.runnerId,
						executionId: request.body?.executionId,
						seq: request.body?.seq,
					})
					?.catch?.(() => {});
			}
			return receipt;
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/verify-sha", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.noteRemoteVerification({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				sha: request.body?.sha ?? null,
				present: request.body?.present,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/complete-execution", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = await executionLedger.completeExecution({
				claimStore,
				taskStore,
				projectStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				sha: request.body?.sha ?? null,
				branch: request.body?.branch ?? null,
				posture: request.body?.posture ?? null,
			});
			if (receipt.duplicate) return receipt;
			// Engine-owned finish: the lease fence accepted the report, so
			// the backend now applies the same transitions as the embedded
			// path (report, survey park, failure routing, advance). The
			// task must still be live and on the reported stage; anything
			// else keeps the accepted report but skips the finish.
			const live = taskStore.getTask(ctx.projectId, request.params.id);
			const terminal = ["complete", "failed"].includes(
				String(live?.status).toLowerCase(),
			);
			if (terminal) {
				return { ...receipt, advanced: false, reason: "task-terminal" };
			}
			const runStage = receipt.reportedStage ?? live?.currentStageId ?? null;
			if (runStage && live?.currentStageId && runStage !== live.currentStageId) {
				return { ...receipt, advanced: false, reason: "stage-moved" };
			}
			const outcome = request.body?.outcome ?? "passed";
			if (outcome !== "passed" && outcome !== "failed") {
				return reply.status(400).send({
					error: "outcome must be passed or failed",
					code: "INVALID_OUTCOME",
				});
			}
			// Runner-authored task files (plan/survey) land in the backend
			// task folder BEFORE the finish advances the task, so a following
			// backend-run CI stage reading {{taskDocs}} can see them.
			materializeRunnerTaskDocs({
				project: projectStore.getProject(ctx.projectId),
				taskId: request.params.id,
				files: request.body?.taskFiles,
			});
			const harnessId =
				runner.facts?.harnesses?.[0]?.id || request.body?.harnessId || "unknown";
			// Runner-run integration: the merge already landed via the
			// leased CAS push — verify read-only, freeze the baseline,
			// and advance. Never the generic stage finish.
			const project = projectStore.getProject(ctx.projectId);
			const allStages = resolveStagesForTask(project, live);
			const currentStage =
				allStages.find((s) => String(s?.id) === String(live?.currentStageId)) || allStages[0] || {};
			if (
				normalizeStageType(currentStage.type) === "merge" &&
				request.body?.integration?.outcome === "landed"
			) {
				const finish = await applyIntegrationReport({
					store: taskStore,
					projectStore,
					projectId: ctx.projectId,
					taskId: request.params.id,
					stage: currentStage,
					stages: allStages,
					integration: request.body.integration,
					runnerId: runner.runnerId,
				});
				return { ...receipt, ...finish };
			}
			// The Runner's explicit served-model field (new runners); normalized
			// through servingModelFor with the stage's kind so CI stages and the
			// "default" sentinel can never land in the report. Old runners omit
			// the field and applyRunnerReport falls back to the dispatch stamp.
			const reportedModelRef = servingModelFor({
				kind: normalizeStageType(currentStage.type),
				model: request.body?.model ?? null,
			});
			const finish = await applyRunnerReport({
				store: taskStore,
				projectStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				outcome: {
					status: outcome,
					output: request.body?.output ?? "",
					summary: request.body?.summary ?? "",
					modifiedFiles: request.body?.modifiedFiles ?? [],
					harnessId,
					modelRef: reportedModelRef,
					failureKind: request.body?.failureKind ?? null,
					failureReason: request.body?.failureReason ?? null,
					duration: request.body?.durationMs
						? String(Number(request.body.durationMs) / 1000)
						: "0.0",
					runnerId: runner.runnerId,
				},
			});
			return { ...receipt, ...finish };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/interrupt", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.interruptExecution({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId ?? null,
				reason: request.body?.reason ?? null,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const claimedRunnerId = request.body?.runnerId;
		if (
			claimedRunnerId &&
			claimedRunnerId !== runner.runnerId
		) {
			return reply.status(403).send({
				error: "Credential does not belong to the claimed Runner.",
				code: "SCOPE_MISMATCH",
			});
		}
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		// Runner self-update floor (Option A, ADR 0012): a known product
		// version below KAINBAIN_RUNNER_MIN_VERSION is refused so it cannot
		// mis-execute — the daemon self-updates on this code and retries.
		const belowMinimum = buildBelowMinimumRefusal({ runner, minVersion: config.runnerMinVersion });
		if (belowMinimum) return reply.status(409).send(belowMinimum);
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return;
		const task = taskStore.getTask(projectId, request.params.id);
		if (!task) return reply.status(404).send({ error: "Task not found" });
		// Operator settings (System Settings › Runners) bind this direct
		// claim exactly like the dispatch scan: a Runner whose project is
		// unloaded, whose job-type switch is off, or whose tool subset
		// excludes the stage harness must not claim the task by asking for
		// it directly. Fail loud (409 + the verdict code) instead of
		// silently honouring a claim the operator switched off.
		const req = taskRequirements(projectStore.getProject(projectId) || {}, task);
		const claimVerdict = operatorConfigVerdict(runner, req, { projectId });
		if (!claimVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} settings refuse this task (${claimVerdict.reason}).`,
				code: claimVerdict.reason,
			});
		}
		// Stage runnerPolicy (stage settings allow/block list) binds this
		// direct claim exactly like the dispatch scan: claiming by task id
		// must not bypass a stage the Runner is not allowed on.
		const claimPolicyVerdict = stageRunnerPolicyVerdict(req.runnerPolicy, runner.runnerId);
		if (!claimPolicyVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is refused by this stage's Runner list (${claimPolicyVerdict.reason}).`,
				code: claimPolicyVerdict.reason,
			});
		}
		try {
			const { executionId, epoch } = claimStore.claim(
				request.params.id,
				runner.runnerId,
				projectId,
			);
			// Same run attribution as the dispatch path: the requirement's
			// resolved harness/model names this run on the timeline/reports.
			const project = projectStore.getProject(projectId);
			const stages = resolveStagesForTask(project, task);
			const stage =
				stages.find((s) => String(s?.id) === String(task.currentStageId)) || stages[0] || null;
			stampDispatchRunAttribution({ taskStore, project, task, stage, stages, req, runnerId: runner.runnerId });
			return { taskId: request.params.id, runnerId: runner.runnerId, executionId, epoch, ...await ciPayloadFor(projectId, task, null), prompt: curateRunnerPrompt({ project, task, stageId: task.currentStageId }) };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim-heartbeat", async (request, reply) => {
		// Lease renewal for long Runner executions (D1): the claim TTL
		// bounds a dead Runner's hold, so a live Runner must extend it
		// while the harness runs — otherwise the hold lapses mid-stage,
		// the task re-queues, and the finisher reports STALE_EPOCH.
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (!hold || hold.runnerId !== runner.runnerId) {
				const err = new Error(
					`Stale execution for task ${request.params.id}: lease belongs to another Runner.`,
				);
				err.statusCode = 409;
				err.code = "STALE_EPOCH";
				throw err;
			}
			// Wall-clock stage timeout (no infinite renewal): a live Runner
			// renewing its lease forever must not outrun the stage budget —
			// otherwise a stuck harness sits claimed indefinitely and the
			// task reads frozen. On breach the hold is released and the
			// stage fails through the normal failure routing (retry/failback),
			// so the task re-queues instead of stranding.
			const project = projectStore.getProject(ctx.projectId);
			const stages = resolveStagesForTask(project, ctx.task);
			const stage =
				stages.find(
					(s) => String(s?.id) === String(ctx.task?.currentStageId),
				) || null;
			const timeoutMs = resolveStageTimeout(
				stage,
				stage?.type,
				config,
				project,
			);
			const { timedOut, elapsedMs } = runnerStageTimeoutStatus({
				startedAt: hold.startedAt ?? null,
				timeoutMs,
			});
			if (timedOut) {
				claimStore.invalidate(request.params.id);
				const reason =
					`Stage timed out after ${elapsedMs}ms (budget ${timeoutMs}ms) ` +
					`on stage '${stage?.name || stage?.id || ctx.task?.currentStageId}'.`;
				try {
					await applyRunnerReport({
						store: taskStore,
						projectStore,
						projectId: ctx.projectId,
						taskId: request.params.id,
						outcome: {
							status: "failed",
							output: "",
							harnessId: runner.facts?.harnesses?.[0]?.id || "unknown",
							failureKind: "timeout",
							failureReason: reason,
							duration: String(elapsedMs / 1000),
							runnerId: runner.runnerId,
						},
					});
				} catch {
					// The 409 below is the contract; a reporting failure must
					// never mask it (the zombie's late finish stays stale).
				}
				return reply.status(409).send({
					error: reason,
					code: "STAGE_TIMEOUT",
					timeoutMs,
					elapsedMs,
				});
			}
			const { epoch } = claimStore.heartbeat(
				request.params.id,
				request.body?.executionId,
			);
			return { taskId: request.params.id, runnerId: runner.runnerId, epoch };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/dispatch", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!runnerRegistry.isFresh(runner)) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is stale — heartbeat, then ask again`,
				code: "STALE_RUNNER",
			});
		}
		// Parked Runners keep heartbeating (freshness is liveness, not
		// eligibility) but take no new work: fail fast here as well as in
		// the per-candidate match, so a paused fleet reads as paused and
		// not "no capable match".
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		// Runner self-update floor (Option A, ADR 0012): same refusal as
		// direct claim — shared helper so the two gates cannot drift.
		const belowMinimum = buildBelowMinimumRefusal({ runner, minVersion: config.runnerMinVersion });
		if (belowMinimum) return reply.status(409).send(belowMinimum);
		if (isTripped(taskStore)) {
			const circuit = circuitSnapshot(taskStore);
			return reply.status(409).send({
				error: "Engine is tripped — dispatch is stopped",
				tripped: true,
				reason: circuit.reason,
				source: circuit.source,
				trippedAt: circuit.trippedAt,
			});
		}
		const projectIds = Array.isArray(request.body?.projectIds)
			? request.body.projectIds
			: undefined;
		runnerRegistry.recordDispatchScope(runner.runnerId, projectIds);
		// D8 burn control (ADR 0010): the fleet cap stops parallel burn
		// before any scan; per-project caps skip that project's candidates
		// below. 0 disables that cap (default: single-Runner behaviour).
		const fleetCap = config.runnerMaxConcurrentFleet || 0;
		if (fleetCap > 0 && claimStore.countLiveHolds() >= fleetCap) {
			return reply.status(429).send({
				error: `Fleet at Runner concurrency cap (${fleetCap}); backing off.`,
				code: "FLEET_CONCURRENCY_EXHAUSTED",
			});
		}
		const projectCap = config.runnerMaxConcurrentPerProject || 0;
		const candidates = scanClaimableTasks(
			{ projectStore, taskStore, claimStore },
			{ projectIds, maxWaitMs: config.dispatchMaxWaitMs || 0 },
		);
		if (candidates.length === 0) {
			return { assigned: false, code: "NO_CLAIMABLE_TASKS" };
		}
		// A harness is dispatch-servable when some active, fresh Runner
		// advertises it. Alias targets on unserved harnesses are skipped
		// for this resolution (share redistributes, per the alias
		// contract); nothing served at all resolves null → loud miss.
		const isHarnessKnown = (name) =>
			runnerRegistry.records().some(
				(rec) =>
					rec?.status === "active" &&
					rec?.paused !== true &&
					runnerRegistry.isFresh(rec) &&
					(rec.capabilities?.harnesses || []).some((h) => h?.id === name),
			);
		const misses = {};
		for (const cand of candidates) {
			let req = cand.req;
			if (cand.req.alias) {
				const resolved = resolveAliasRequirement({
					project: projectStore.getProject(cand.projectId),
					aliasName: cand.req.alias,
					isHarnessKnown,
				});
				if (!resolved) {
					misses.ALIAS_UNRESOLVED = (misses.ALIAS_UNRESOLVED || 0) + 1;
					continue;
				}
				req = {
					...cand.req,
					harness: resolved.harness,
					model: resolved.model,
					alias: { name: resolved.aliasName, targetIndex: resolved.targetIndex },
				};
			}
			// The candidate's project travels alongside the requirements so
			// the operator project-scope check in `runnerMatches` can
			// refuse out-of-scope projects loudly (PROJECT_SCOPE) instead
			// of dispatching work the operator unloaded for this Runner.
			const verdict = runnerMatches(runner, req, {
				staleAfterMs: runnerRegistry.staleAfterMs,
				projectId: cand.projectId,
			});
			if (!verdict.ok) {
				misses[verdict.reason] = (misses[verdict.reason] || 0) + 1;
				continue;
			}
			if (
				projectCap > 0 &&
				claimStore.countLiveHolds({ projectId: cand.projectId }) >= projectCap
			) {
				misses.PROJECT_BUSY = (misses.PROJECT_BUSY || 0) + 1;
				continue;
			}
			// Merge stages dispatch as leased `integrate` jobs (Step 4): the
			// task claim fences progress/logs/completion exactly like any
			// stage, while the integration lease serializes target-branch
			// writes. A busy integration slot backs the Runner off to poll
			// again (the request stays queued — never lost, never doubled).
			if (req.kind === "merge") {
				let attempt;
				try {
					attempt = await prepareIntegrationAttempt({
						taskStore,
						projectStore,
						projectId: cand.projectId,
						task: cand.task,
					});
				} catch (err) {
					if (err?.code === "INTEGRATION_UNPREPARED") {
						misses.INTEGRATION_UNPREPARED = (misses.INTEGRATION_UNPREPARED || 0) + 1;
						continue;
					}
					return sendStoreError(reply, err);
				}
				let executionId;
				let epoch;
				try {
					({ executionId, epoch } = claimStore.claim(cand.taskId, runner.runnerId, cand.projectId));
				} catch (err) {
					if (err?.code === "CLAIM_CONFLICT") continue;
					return sendStoreError(reply, err);
				}
				if (!integrationQueue) {
					claimStore.invalidate(cand.taskId);
					misses.NO_INTEGRATION_QUEUE = (misses.NO_INTEGRATION_QUEUE || 0) + 1;
					continue;
				}
				integrationQueue.enqueue({
					projectId: cand.projectId,
					targetBranch: attempt.targetBranch,
					taskId: cand.taskId,
					taskBranch: attempt.taskBranch,
					expectedTaskSha: attempt.expectedTaskSha,
					expectedTargetSha: attempt.expectedTargetSha,
					mergeAttemptId: attempt.mergeAttemptId,
				});
				let lease;
				try {
					lease = integrationQueue.acquire({
						projectId: cand.projectId,
						targetBranch: attempt.targetBranch,
						runnerId: runner.runnerId,
					});
				} catch (err) {
					claimStore.invalidate(cand.taskId);
					if (err?.code === "INTEGRATION_BUSY") {
						return { assigned: false, code: "INTEGRATION_BUSY" };
					}
					return sendStoreError(reply, err);
				}
				if (!lease.leased) {
					claimStore.invalidate(cand.taskId);
					misses.INTEGRATION_EMPTY = (misses.INTEGRATION_EMPTY || 0) + 1;
					continue;
				}
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					kind: "integrate",
					integration: {
						taskBranch: attempt.taskBranch,
						expectedTaskSha: attempt.expectedTaskSha,
						targetBranch: attempt.targetBranch,
						expectedTargetSha: attempt.expectedTargetSha,
						mergeAttemptId: attempt.mergeAttemptId,
						integrationExecutionId: lease.executionId,
						integrationEpoch: lease.epoch,
					},
					requirements: req,
				};
			}
			try {
				const { executionId, epoch } = claimStore.claim(
					cand.taskId,
					runner.runnerId,
					cand.projectId,
				);
				// Stamp the matched harness/model/alias onto the task so the
				// timeline and reports attribute THIS run (mirrors the
				// embedded dispatch stamp); CI/merge stamp nothing.
				const candProject = projectStore.getProject(cand.projectId);
				stampDispatchRunAttribution({
					taskStore,
					project: candProject,
					task: cand.task,
					stage: cand.stage,
					stages: resolveStagesForTask(candProject, cand.task),
					req,
					runnerId: runner.runnerId,
				});
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					prompt: curateRunnerPrompt({ project: candProject, task: cand.task, stageId: cand.stage?.id }),
					...await ciPayloadFor(cand.projectId, cand.task, cand.stage),
					requirements: req,
				};
			} catch (err) {
				if (err?.code === "CLAIM_CONFLICT") continue;
				return sendStoreError(reply, err);
			}
		}
		return { assigned: false, code: "NO_CAPABLE_MATCH", misses };
	});

	// ---- Integration leases (Step 3: serialized Runner-run merges) ---------
	// The backend never merges or pushes: it queues merge requests
	// (enqueue is backend-internal, called by the merge stage) and leases
	// the head entry to one Runner per project + target branch. The Runner
	// holds `executionId`/`epoch` exactly like a task claim; a superseded
	// report is stale by construction.
	app.post("/runners/integration/acquire", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		// Paused Runners take no new work on any route (mirrors the claim
		// and dispatch routes), and the operator's Runs-merges switch and
		// project scope bind this direct lease exactly like a dispatched
		// merge: acquiring a merge lease must not bypass Settings.
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		const mergeVerdict = operatorConfigVerdict(
			runner,
			{ kind: "merge" },
			{ projectId: request.body?.projectId },
		);
		if (!mergeVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} settings refuse merge work (${mergeVerdict.reason}).`,
				code: mergeVerdict.reason,
			});
		}
		// Stage runnerPolicy binds the direct merge lease exactly like a
		// dispatched merge: peek the head queued entry (the lease about to
		// be granted), resolve its task's stage, and refuse Runners the
		// stage does not allow. Anything unresolvable fails open to the
		// legacy lease — an empty queue still reports leased:false below.
		const acquireProjectId = request.body?.projectId;
		const acquireBranch = request.body?.targetBranch;
		if (acquireProjectId && acquireBranch) {
			const headEntry = integrationQueue.peekHead({ projectId: acquireProjectId, targetBranch: acquireBranch });
			if (headEntry?.taskId) {
				const headTask = taskStore.getTask(acquireProjectId, headEntry.taskId);
				if (!headTask) {
					// Task vanished (deleted while queued) — fall through to the
					// queue acquire; it will handle stale entries.
				} else {
					const headStages = resolveStagesForTask(projectStore.getProject(acquireProjectId), headTask);
					const headStage = (Array.isArray(headStages) ? headStages : []).find(
						(s) => String(s?.id) === String(headTask?.currentStageId),
					) || null;
					const leaseVerdict = stageRunnerPolicyVerdict(headStage, runner.runnerId);
					if (!leaseVerdict.ok) {
						return reply.status(409).send({
							error: `Runner ${runner.runnerId} is refused by this stage's Runner list (${leaseVerdict.reason}).`,
							code: leaseVerdict.reason,
						});
					}
				}
			}
		}
		try {
			return integrationQueue.acquire({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				runnerId: runner.runnerId,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/heartbeat", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			return integrationQueue.heartbeat({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/report", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			const receipt = integrationQueue.report({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				outcome: request.body?.outcome,
				mergeSha: request.body?.mergeSha ?? null,
				detail: request.body?.detail ?? null,
			});
			return { ...receipt, runnerId: runner.runnerId };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners/integration", async (request) => {
		if (!integrationQueue) return { depth: 0, lease: null, counters: {} };
		return {
			...integrationQueue.describe({
				projectId: request.query?.projectId,
				targetBranch: request.query?.targetBranch,
			}),
			counters: integrationQueue.snapshot(),
		};
	});

	// ---- Steering acks (D5, ADR 0011) --------------------------------------
	// The unified POST /tasks/:id/steer (taskFlowRoutes) queues against the
	// live lease; the Runner pulls on heartbeat and acks here.
	app.post("/tasks/:id/steer-ack", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (
				!hold ||
				hold.executionId !== request.body?.executionId ||
				hold.epoch !== request.body?.epoch ||
				hold.runnerId !== runner.runnerId
			) {
				return reply.status(409).send({
					error: `Ack targets a superseded execution (no matching live lease).`,
					code: "STALE_EPOCH",
				});
			}
			return steerStore.ack(request.body.executionId, request.body?.steerId, {
				ok: request.body?.ok,
				detail: request.body?.detail,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/tasks/:id/steers", async (request, reply) => {
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		const executionId = request.query?.executionId;
		if (!executionId || typeof executionId !== "string") {
			return reply.status(400).send({
				error: "steers requires an executionId query.",
				code: "INVALID_STEER_ARGS",
			});
		}
		return {
			taskId: request.params.id,
			executionId,
			pending: steerStore.pendingFor(executionId),
			receipts: steerStore.receiptsFor(executionId),
		};
	});
};

import { generateStageReportContent } from "../../watch/index.js";
import { redactSecretsText } from "../../../shared/redactSecrets.js";
import { recordReliabilitySample } from "../../watch/reliabilityShared.js";
import { stageWantsReport } from "../../promptCuration.js";
import { stageElapsedSeconds } from "../stagePolicy.js";
import { resolveStagesForTask } from "../stageResolution.js";
import { normalizeStageType } from "../../projectStore.js";
import { ALIAS_HARNESS_ID } from "../../../shared/modelAliases.js";
import { routeStageError } from "./routeStageError.js";
import { parkTaskForSurvey } from "./parkTaskForSurvey.js";

/***
 * MARK: applyRunnerReport
 * @description Engine-owned finish for a Runner-reported stage (remote
 *   dispatch integration, ADR 0009 step 6). The Runner owns git
 *   (clone/worktree/commit/push — transport row 1/2, D2: the backend never
 *   touches remotes for Runner work); the backend owns everything else,
 *   composing the SAME standalone transitions as the embedded path:
 *   formal report save (opt-in stages), reliability sample, question-me
 *   survey park (shared with executeStage — a remote run can never skip
 *   the human survey), failure routing via routeStageError, and
 *   advanceStage plus the scheduler follow-on kick. Call only after the
 *   lease fence accepted the execution (complete-execution does that).
 * @example await applyRunnerReport({ store, projectStore, projectId: 'p', taskId: 't', outcome: { status: 'passed', output: '...' } }) => { advanced: true, ... }
 * @param {Object} args - Context.
 * @param {Object} args.store - Task store.
 * @param {Object} args.projectStore - Project store.
 * @param {string} args.projectId - Project id.
 * @param {string} args.taskId - Task id.
 * @param {Object} args.outcome - Runner outcome.
 * @param {string} args.outcome.status - `passed` or `failed`.
 * @param {string} [args.outcome.output] - Final assistant text.
 * @param {string} [args.outcome.summary] - Run summary.
 * @param {Array} [args.outcome.modifiedFiles] - Modified files.
 * @param {string} [args.outcome.harnessId] - Harness that ran.
 * @param {string|null} [args.outcome.modelRef] - Served model the Runner
 *   reported (already normalized: null for CI/merge/harness-managed).
 *   Falls back to the dispatch-time `currentRunAttribution`, then to the
 *   stage slot, so the persisted report names the model that actually ran.
 * @param {string} [args.outcome.failureKind] - Failure taxonomy kind.
 * @param {string} [args.outcome.failureReason] - Failure message.
 * @param {string} [args.outcome.duration] - Run duration seconds.
 * @param {string} [args.outcome.runnerId] - Reporting Runner.
 * @returns {Promise<Object>} `{ advanced, status, ... }`.
 ***/
export async function applyRunnerReport({
	store,
	projectStore,
	projectId,
	taskId,
	outcome,
}) {
	const task = store.getTask(projectId, taskId);
	if (!task) {
		const err = new Error(`Task ${taskId} not found`);
		err.statusCode = 404;
		err.code = "TASK_NOT_FOUND";
		throw err;
	}
	const project = projectStore?.getProject?.(projectId);
	// The runner's completion payload (final assistant text, summaries) is
	// committed to the repository via stage reports and task markdown — the
	// same guarantee as the live log path: redact before persistence.
	// Structured log entries ingested live are already redacted at creation.
	const redactedOutput = redactSecretsText(outcome.output || "");
	const redactedSummary = redactSecretsText(outcome.summary || "");
	const stages = resolveStagesForTask(project, task);
	const stage =
		stages.find(
			(s) =>
				String(s.id) === String(task.currentStageId) ||
				(s.name &&
					String(s.name).toLowerCase() ===
						String(task.currentStageId).toLowerCase()),
		) ||
		stages[0] || { id: "stage", name: "Stage", type: "agent" };
	const stageType = normalizeStageType(stage.type);
	const bridge = store.eventBridge;
	const cwd = project?.cwd;
	const via = outcome.runnerId ? `via Runner ${outcome.runnerId}` : "via Runner";
	const duration = outcome.duration || "0.0";
	// The served model for the persisted report: the Runner's explicit report
	// wins, then the dispatch-time stamp (what the Runner was matched on),
	// then the stage slot. Blank/"default" values are absent, never worded —
	// scripted stages record no model at all.
	const dispatchAttribution =
		task.currentRunAttribution &&
		String(task.currentRunAttribution.stageId) === String(task.currentStageId)
			? task.currentRunAttribution
			: null;
	const cleanRef = (value) =>
		typeof value === "string" && value.trim() && value.trim().toLowerCase() !== "default"
			? value.trim()
			: null;
	// The stage slot is a last-resort fallback only: on an alias-harness
	// stage `stage.model` is the ALIAS NAME, not a model, so it must never be
	// recorded as the run's modelRef.
	const stageHarnessIsAlias =
		String(stage.harness ?? project?.harness ?? "") === ALIAS_HARNESS_ID;
	const reportModelRef =
		cleanRef(outcome.modelRef) ??
		cleanRef(dispatchAttribution?.modelRef) ??
		(stageHarnessIsAlias ? null : cleanRef(stage.model));
	const reportAliasName = cleanRef(dispatchAttribution?.aliasName);
	const reportTargetIndex = Number.isInteger(dispatchAttribution?.targetIndex)
		? dispatchAttribution.targetIndex
		: null;

	if (outcome.status === "failed") {
		const err = new Error(outcome.failureReason || "Stage failed on the Runner");
		// The runner's completion payload carries the tail of the run output
		// (runner/daemon.js caps it). Keep it on the error so the failure
		// report renders the actual failing output instead of only the
		// reason — thin "exit code 1" reports hid every branch result
		// (task b5716327). handleStageFailure already renders error.stdout
		// into the report, lastError, and timeline excerpt.
		if (redactedOutput) err.stdout = redactedOutput;
		return routeStageError(
			store,
			projectId,
			taskId,
			stage,
			err,
			{
				stages,
				bridge,
				projectCwd: cwd,
				runOutcome: {
					harnessId: outcome.harnessId,
					// The served model/alias names the failed run on its
					// timeline row too (blank for scripted stages).
					modelRef: reportModelRef,
					aliasName: reportAliasName,
					targetIndex: reportTargetIndex,
					// The reporting Runner names the failed run on its
					// timeline row and failure report, so a struggling
					// Runner can be spotted per stage or task type later.
					runnerId: outcome.runnerId,
					failureKind: outcome.failureKind,
				},
				classifyAs: {
					failureKind: outcome.failureKind,
					failureReason: outcome.failureReason,
				},
			},
		);
	}

	const at = Date.now();
	recordReliabilitySample(store, projectId, taskId, {
		harnessId: outcome.harnessId || "unknown",
		failureKind: "none",
		at,
		atRaw: new Date(at).toISOString(),
		stageId: stage.id,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[SYSTEM] Stage '${stage.name || stage.id}' completed in ${duration}s (${via})`,
		{ taskId, stageId: stage.id, duration },
	);

	if (stageWantsReport(stage)) {
		const reportContent = generateStageReportContent({
			task,
			stage,
			output: redactedOutput,
			summary: redactedSummary,
			modifiedFiles: outcome.modifiedFiles || [],
			status: "PASSED",
			duration,
		});
		store.saveStageReport(projectId, taskId, {
			stageName: stage.name || stage.id,
			stageId: stage.id,
			duration: stageElapsedSeconds(task),
			status: "PASSED",
			content: reportContent,
			projectCwd: cwd,
			harnessId: outcome.harnessId,
			failureKind: outcome.failureKind || "none",
			// The served model/alias the run actually used (Runner-reported,
			// else the dispatch stamp) — absent for scripted stages, so their
			// reports and cards never name a model.
			modelRef: reportModelRef,
			aliasName: reportAliasName,
			targetIndex: reportTargetIndex,
			runnerId: outcome.runnerId,
		});
	}

	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Agent stage completed: ${stage.name || stage.id} (${via})`,
		// Structured Runner id alongside the `via Runner …` prose, so
		// consumers need not parse the action string. Blank-safe: an
		// absent Runner stays absent, never worded.
		...(typeof outcome.runnerId === "string" && outcome.runnerId.trim()
			? { runnerId: outcome.runnerId.trim() }
			: {}),
	});
	store._saveTaskMarkdown(cwd, task);

	const surveyPark = parkTaskForSurvey({
		store,
		projectId,
		taskId,
		task,
		stage,
		projectObj: project,
		cwd,
		bridge,
		stageType,
		finalOutput: redactedOutput,
		streamedOutput: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		duration,
		via,
	});
	if (surveyPark.parked) return { advanced: false, ...surveyPark.response };

	task.surveyPending = false;
	task.infraRetryCount = 0;
	store.advanceStage(projectId, taskId, stages, bridge, cwd);

	store.lastCompletedTask = { projectId, taskId, timestamp: Date.now() };
	if (store.schedulerRunning) {
		setTimeout(() => {
			store.scheduleTick().catch(() => {});
		}, 50);
	}

	return {
		advanced: true,
		task,
		stageType,
		status: "passed",
		output: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		// The served model that actually ran (Runner-reported > dispatch
		// stamp > stage slot), not just the configured slot.
		model: reportModelRef,
		duration,
	};
}

import { git } from "../../git.js";
import {
	isValidReviewBaseline,
	shouldResetReviewBaseline,
} from "../../work/taskBranches.js";
import {
	finalizePassedCommandStage,
	isMergeLanded,
} from "../commandStages.js";
import { _appendProcessLog } from "../../watch/index.js";
import { recordReliabilitySample } from "../../watch/reliabilityShared.js";

/***
 * MARK: applyIntegrationReport
 * @description Engine-owned finish for a Runner-run integration (Step 4):
 *   the integration Runner merged `origin/<taskBranch>` into the target in
 *   an ephemeral worktree and CAS-pushed the target. The backend verifies
 *   read-only (fetch + ancestry — never a checkout, merge, or push), freezes
 *   the PR-review baseline from the reported SHAs, saves the merge report,
 *   and advances. A verification failure parks the task `failed` on the
 *   merge stage (`skipFailback`, sync-blocked diagnostic) instead of
 *   rewinding a merge that may have landed.
 * @example await applyIntegrationReport({ store, projectStore, projectId: 'p', taskId: 't', stage, stages, integration: { mergeSha: 'a', ... } }) => { advanced: true }
 * @param {Object} args - Context.
 * @param {Object} args.store - Task store.
 * @param {Object} args.projectStore - Project store.
 * @param {string} args.projectId - Project id.
 * @param {string} args.taskId - Task id.
 * @param {Object} args.stage - Resolved merge stage.
 * @param {Array} [args.stages] - Full stage list.
 * @param {Object} args.integration - Runner report (`mergeSha`, `targetBranch`, `taskBranch`, `expectedTaskSha`, `expectedTargetSha`, `mergeAttemptId`).
 * @param {string} [args.runnerId] - Reporting Runner.
 * @returns {Promise<Object>} `{ advanced, ... }`.
 ***/
export async function applyIntegrationReport({
	store,
	projectStore,
	projectId,
	taskId,
	stage,
	stages = [],
	integration,
	runnerId = null,
}) {
	const task = store.getTask(projectId, taskId);
	if (!task) {
		const err = new Error(`Task ${taskId} not found`);
		err.statusCode = 404;
		err.code = "TASK_NOT_FOUND";
		throw err;
	}
	const project = projectStore?.getProject?.(projectId);
	const cwd = project?.cwd;
	const bridge = store.eventBridge;
	const taskShortId = String(task.id).slice(0, 4).toUpperCase();
	const via = runnerId ? `via Runner ${runnerId}` : "via Runner";
	const { mergeSha, targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId } = integration || {};

	const parkUnverifiable = (message, diagnostics) => {
		const err = new Error(message);
		err.gitDiagnostics = { kind: "sync-blocked", ...(diagnostics || {}) };
		_appendProcessLog(task, `[ERROR] ${message}`);
		try {
			store._saveTaskMarkdown(cwd, task);
		} catch {
			// Parking matters more than the warning.
		}
		return store.handleStageFailure(projectId, taskId, stage, err, {
			stages,
			bridge,
			projectCwd: cwd,
			skipFailback: true,
			// The reporting Runner names the parked failure row and
			// report, like every other Runner-run failure.
			runnerId,
		});
	};

	if (!mergeSha || !targetBranch || !taskBranch) {
		return parkUnverifiable(
			`Integration report from ${via} is missing mergeSha/targetBranch/taskBranch — cannot verify the merge; retry the merge stage.`,
			{ taskBranch, mainBranch: targetBranch },
		);
	}

	// Idempotent re-entry: a landed marker for this stage means a duplicate
	// report (retry, resume) must not advance twice.
	if (isMergeLanded(task, { stageId: stage?.id })) {
		_appendProcessLog(task, `[MERGE] Duplicate integration report for '${taskBranch}' ignored (merge already landed ${task.reviewBaseline?.mergedAt || "previously"})`);
		try {
			store._saveTaskMarkdown(cwd, task);
		} catch {
			// Advisory only.
		}
		return { advanced: false, status: "passed", duplicate: true };
	}

	// Read-only verification: fetch, then prove the merge commit is an
	// ancestor of the remote target tip. The backend never checks out,
	// merges, or pushes here.
	let targetTip = null;
	let landed = false;
	try {
		await git(cwd, ["fetch", "origin"], { timeout: 60000 });
		targetTip = (await git(cwd, ["rev-parse", "--verify", `origin/${targetBranch}`])).stdout.trim() || null;
		if (targetTip) {
			await git(cwd, ["merge-base", "--is-ancestor", mergeSha, targetTip]);
			landed = true;
		}
	} catch {
		landed = false;
	}
	if (!landed) {
		return parkUnverifiable(
			`Integration of '${taskBranch}' reported merge ${String(mergeSha).slice(0, 7)} by ${via}, but the backend cannot find it on 'origin/${targetBranch}' (tip ${targetTip ? targetTip.slice(0, 7) : "unknown"}) — the push may not have stuck. Retry the merge stage to re-verify; a landed merge is never rewound.`,
			{ taskBranch, mainBranch: targetBranch, sourceSha: mergeSha, targetSha: targetTip },
		);
	}

	// Freeze the PR-review baseline from the reported SHAs (same shape as
	// the embedded merge path; keep-first projects keep their baseline).
	const mergedAt = new Date().toISOString();
	const existing = isValidReviewBaseline(task.reviewBaseline) ? task.reviewBaseline : null;
	if (!(existing && !shouldResetReviewBaseline(project))) {
		const baseline = {
			baseSha: expectedTargetSha || targetTip,
			headSha: expectedTaskSha || mergeSha,
			mainSha: mergeSha,
			mergedAt,
			stageId: stage?.id || null,
		};
		task.reviewBaseline = baseline;
		task.history.push({
			timestamp: mergedAt,
			action: `Recorded PR-review baseline for '${taskBranch}' at Runner-run merge into '${targetBranch}' (${String(mergeSha).slice(0, 7)})`,
			...(typeof runnerId === "string" && runnerId.trim()
				? { runnerId: runnerId.trim() }
				: {}),
		});
		if (typeof store.updateTask === "function" && task.id) {
			store.updateTask(projectId, taskId, { reviewBaseline: baseline }, cwd);
		}
	}
	task.mergeAttemptId = mergeAttemptId || task.mergeAttemptId;
	task.preMergeMainSha = expectedTargetSha || task.preMergeMainSha;
	task.pendingPushVerification = {
		sha: mergeSha,
		branch: targetBranch,
		verified: true,
		verifiedAt: mergedAt,
		verifiedBy: runnerId || "backend-fetch",
	};

	const at = Date.now();
	recordReliabilitySample(store, projectId, taskId, {
		harnessId: "integration",
		failureKind: "none",
		at,
		atRaw: new Date(at).toISOString(),
		stageId: stage?.id,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[GIT] Task #KB-${taskShortId}: Runner-run merge landed '${taskBranch}' into '${targetBranch}' (${String(mergeSha).slice(0, 7)} ${via})`,
		{ taskId },
	);

	const reportContent = [
		`# Merge Stage Report: ${stage?.name || stage?.id || "merge"}`,
		`**Task branch:** ${taskBranch}`,
		`**Main branch:** ${targetBranch}`,
		`**Status:** PASSED`,
		`**Merge SHA:** ${mergeSha}`,
		`**Landed at:** ${mergedAt}`,
		`**Integrated by:** ${via} (leased integration, ephemeral worktree)`,
	].join("\n");

	const result = await finalizePassedCommandStage(store, projectId, taskId, stage, {
		stages,
		cwd,
		bridge,
		kind: "merge",
		label: "Merge",
		reportContent,
		historyAction: `Merge stage passed: '${taskBranch}' integrated into '${targetBranch}' by ${via}`,
		runnerId,
	});
	_appendProcessLog(task, `[MERGE] Verified Runner-run merge ${String(mergeSha).slice(0, 7)} on 'origin/${targetBranch}' and advanced`);
	try {
		store._saveTaskMarkdown(cwd, task);
	} catch {
		// Finalize already persisted what matters.
	}
	return { ...result, advanced: true, mergeSha, verified: true };
}

import {
	isBranchModeEnabled,
} from "../../../work/index.js";
import {
	_appendProcessLog,
	generateStageReportContent,
} from "../../../watch/index.js";
import {
	emitAlert,
	maybeEmitFailbackWarning,
	resolveAlertSeverity,
} from "../../../observability/alerts.js";
import {
	isTerminalTaskStatus,
	stageElapsedSeconds,
} from "../../stagePolicy.js";
import {
	consumeStallHandled,
} from "../../stageHeartbeat.js";
import {
	isTripped,
} from "../../circuitBreaker.js";
import {
	recordCircuitFailure,
} from "../../circuitSensors.js";
import {
	buildTimelineAttribution,
} from "../../runAttribution.js";
import {
	beginAutoIteration,
	classificationMetaOf,
	excerptLog,
	fireStageErrorPush,
	gitDiagnosticsOf,
	resolveFailureProject,
	resolveStageErrorPushReason,
} from '../resolvers/index.js';
import { settleOperatorAbort } from './settleOperatorAbort.js';
import { deferForCircuitTrip } from './deferForCircuitTrip.js';
import { shouldSuppressProjectBlockerAlert } from './shouldSuppressProjectBlockerAlert.js';
import { parkedAlertStructuredFields } from './parkedAlertStructuredFields.js';
import { handleTransientFailure } from './handleTransientFailure.js';

/***
 * MARK: handleStageFailure
 * @description Handles stage execution failure: logs error, generates failure report, emits events, and routes to fallback stage.
 * @param {Object} taskStore - TaskStore instance.
 * @param {string} projectId
 * @param {string} taskId
 * @param {Object} stage
 * @param {Error|string} error
 * @param {Object} [opts]
 * @param {Array<Object>} [opts.stages]
 * @param {Object} [opts.bridge]
 * @param {string} [opts.projectCwd]
 * @param {string} [opts.fallbackStageId]
 * @param {boolean} [opts.skipFailback=false]
 * @param {boolean} [opts.compactionHint=false] - Context-overflow routing:
 *   fail back (never instant-park) so the next attempt can compact the
 *   prompt/history instead of retrying the identical overflowing context.
 * @param {Object} [opts.project] - Explicit project for budget resolution (else the store lookup).
 * @param {string} [opts.harnessId] - Harness that ran the failed stage (reliability attribution; recorded on the failure report when present).
 * @param {string} [opts.failureKind] - Runner outcome kind ("rejected" or "infrastructure"); recorded on the failure report and on task.lastError when known, so the task view can label deliberate rejections instead of generic failures.
 * @param {string} [opts.aliasName] - Model alias the failed run resolved through (per-alias reliability attribution).
 * @param {string} [opts.modelRef] - Concrete model the alias target dispatched.
 * @param {number} [opts.targetIndex] - Weighted-target index of the alias pick (informational).
 * @param {string} [opts.runnerId] - Runner that ran the failed stage (recorded on the failure timeline row and report when present, so a struggling Runner can be spotted per stage or task type later; absent for embedded runs).
 * @returns {Object} Failure routing result. When automatic recovery starts,
 *   `status` is the internal routing signal `"retrying"` for BOTH re-run
 *   shapes (kept stable for the scheduler and its tests) — user display must
 *   derive from the task flags instead: `autoRetrying` (same-stage in-place
 *   retry) vs `autoIterating` (cross-stage continuation). The `stage:auto_retry`
 *   event carries `sameStage` with that same verdict, and the `[AUTO]` system
 *   log says "retrying same stage" vs "continuing at" accordingly.
  * @example handleStageFailure(store, "p1", "t1", stage, err, {}) => { status: "parked", … }
 ***/
export function handleStageFailure(
	taskStore,
	projectId,
	taskId,
	stage,
	error,
	opts = {},
) {
	const {
		stages = [],
		bridge = taskStore.eventBridge,
		projectCwd,
		fallbackStageId,
		skipFailback = false,
		compactionHint = false,
		harnessId,
		failureKind,
		aliasName,
		modelRef,
		targetIndex,
		runnerId,
	} = opts;
	const failureProject = resolveFailureProject(taskStore, projectId, opts);
	const task = taskStore.getTask(projectId, taskId);
	if (!task) return null;
	// WP6 watchdog de-duplication: the stall watchdog already terminated this
	// run and routed it through `handleTransientFailure` with `{ stall: true }`.
	// The terminated child settles with a non-zero exit and would otherwise
	// fail back immediately after the transient retry; suppress that duplicate
	// exactly once.
	if (consumeStallHandled(taskStore, taskId)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: "stalled",
			message:
				"Stage stall already handled by the watchdog; duplicate failure routing suppressed",
		};
	}
	// Single taxonomy, classified once per failure for auditability.
	const { classification, classificationMeta } = classificationMetaOf(error);
	// Context overflow never parks instantly: it fails back so the next
	// attempt compacts the prompt/history. An explicit compactionHint opts in
	// even when the caller parked unrecoverable errors by default.
	const compactionHintEffective =
		compactionHint === true || classification.signal === "context-overflow";
	const effectiveSkipFailback =
		compactionHint === true ? false : skipFailback;
	// A failure settling after the operator finished the task (complete,
	// fail/park, cancel) must not resurrect it via failback or auto-retry.
	if (isTerminalTaskStatus(task.status)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: task.status,
			message: `Task is already ${task.status}; failure ignored`,
		};
	}
	// A run aborted by pause settles here: the pause must stick, so neither
	// failback nor auto-retry may move the task back into the queue.
	if (String(task.status).toLowerCase() === "paused") {
		return {
			task,
			stageType: stage?.type || "agent",
			status: "paused",
			message: "Task is paused; failure does not fail back",
		};
	}
	// A run superseded by an operator move settles here: the move already
	// parked the task at its destination, so the orphaned run's outcome must
	// not be attributed to the new stage. Command stages surface the kill as
	// a plain non-zero exit (no operator-abort marker), which would otherwise
	// fail back with a spurious failureReason and auto-retry, undoing the
	// move (task 072e2cfa). Match on the recorded stage so only that orphaned
	// run is quieted; the marker is consumed either way so a later genuine
	// failure in the destination stage routes normally. An unknown failing
	// stage (null) is treated as the orphaned run: the operator's explicit
	// move sticks, and the task parks at its destination where a retry is
	// always available — failing safe toward operator intent, never toward
	// an automatic failback that would undo it.
	if (task.supersededStageId != null) {
		const superseded = String(task.supersededStageId);
		const failingId = stage?.id != null ? String(stage.id) : null;
		const currentId =
			task.currentStageId != null ? String(task.currentStageId) : null;
		delete task.supersededStageId;
		if (
			currentId !== superseded &&
			(failingId === null || failingId === superseded)
		) {
			return settleOperatorAbort(taskStore, projectId, taskId, stage, error, {
				bridge,
				projectCwd,
			});
		}
	}

	// An operator-initiated abort carries no actionable failure: settle
	// quietly without failback, retry, or budget, whatever the status.
	if (classification.kind === "operator-abort") {
		return settleOperatorAbort(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
		});
	}

	// Tier-5 gate: record the failure against the trip sensors first (this
	// call may itself trip the engine), then quiet-defer instead of failing
	// back, auto-retrying, or burning any budget while containment holds.
	recordCircuitFailure(taskStore, { taskId, error, failureKind });
	if (isTripped(taskStore)) {
		const deferral = deferForCircuitTrip(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
			failureKind,
		});
		if (deferral && !deferral.continueNormalHandling) return deferral;
	}

	// A task parked as interrupted by an engine stop keeps that state so
	// resume/retry starts clean: genuine failures are recorded for feedback
	// but never move the task or spend iteration budget by themselves.
	const wasInterrupted = String(task.status).toLowerCase() === "interrupted";

	const errorMsg =
		typeof error === "string"
			? error
			: error?.message || "Stage execution failed";
	const cwd = taskStore._resolveProjectCwd(projectId, projectCwd);
	const stageType = stage?.type || "agent";
	const stderrText = error?.stderr ? String(error.stderr).trim() : "";
	const stdoutText = error?.stdout ? String(error.stdout).trim() : "";
	task.failureReason = errorMsg;
	task.lastError = {
		message: errorMsg,
		stageId: stage?.id,
		stageName: stage?.name || stage?.id,
		stageType,
		stderr: stderrText,
		stdout: stdoutText,
		...(failureKind ? { failureKind } : {}),
		...(gitDiagnosticsOf(error) ? { gitDiagnostics: gitDiagnosticsOf(error) } : {}),
		classification: classificationMeta,
		...(compactionHintEffective ? { compactionHint: true } : {}),
		timestamp: new Date().toISOString(),
	};
	if (!Array.isArray(task.history)) {
		task.history = [];
	}
	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Stage failed in '${stage?.name || stage?.id || "unknown"}': ${errorMsg}`,
	});
	_appendProcessLog(task, `[ERROR] ${errorMsg}`);
	taskStore._saveTaskMarkdown(cwd, task);

	const failureDuration = stageElapsedSeconds(task);
	// Timeline attribution for the failed run: the resolved harness/model/
	// alias this attempt dispatched through, straight from the routing opts
	// (never a second resolution). A failure with no attribution (command
	// stages, pre-contract runs) spreads nothing — the row stays blank by
	// omission, never placeholder-worded.
	const runAttribution = buildTimelineAttribution({
		harnessId,
		aliasName,
		modelRef,
		targetIndex,
		runnerId,
	});
	taskStore._recordTimelineWithDiffStat(
		task,
		{
			stage: stage?.name || stage?.id || task.currentStageId,
			status: "Failed",
			duration: failureDuration === undefined ? "--" : `${failureDuration}s`,
			durationSeconds: failureDuration,
			durationStageId: stage?.id || task.currentStageId,
			durationStartedAt: task.enteredStageAt,
			timestamp: new Date().toISOString(),
			reason: errorMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			classification: classificationMeta,
			...(compactionHintEffective ? { compactionHint: true } : {}),
			...(stderrText ? { stderr: excerptLog(stderrText) } : {}),
			...(stdoutText ? { stdout: excerptLog(stdoutText) } : {}),
			...(runAttribution || {}),
		},
		cwd,
		{ useBranches: isBranchModeEnabled(taskStore.projectStore, projectId) },
	);
	const failureReport = generateStageReportContent({
		task,
		stage,
		output: error?.stdout || errorMsg,
		summary: `Execution failed: ${errorMsg}`,
		status: "FAILED",
		duration: stageElapsedSeconds(task),
		error: errorMsg,
	});

	taskStore.saveStageReport(projectId, taskId, {
		stageName: stage?.name || stage?.id || "Stage",
		stageId: stage?.id,
		duration: stageElapsedSeconds(task),
		status: "FAILED",
		content: failureReport,
		projectCwd: cwd,
		harnessId,
		failureKind,
		aliasName,
		modelRef,
		targetIndex,
		runnerId,
		// Failure traces keep the `-failure-` filename infix so they stay
		// distinguishable from opt-in success reports in the docs folder.
		failure: true,
	});

	// The user-facing error toast is NOT emitted here: at this point routing
	// does not know yet whether the failure auto-retries or fails back into
	// continued work. Toasting unconditionally pages the operator for
	// failures that recover on their own. The toast fires below, only when
	// the task actually parks without automatic recovery.
	bridge?.emitSystemLog?.(
		projectId,
		`[CLASSIFY] Stage '${stage?.name || stage?.id}' error on task #${task.id?.slice(0, 4)}: kind=${classificationMeta.kind} signal=${classificationMeta.signal} retryable=${classificationMeta.retryable}`,
		{ taskId, stageId: stage?.id, classification: classificationMeta },
	);
	bridge?.emitSystemLog?.(
		projectId,
		`[ERROR] Stage '${stage?.name || stage?.id}' failed on task #${task.id?.slice(0, 4)}: ${errorMsg}`,
		{ taskId, stageId: stage?.id, error: errorMsg, classification: classificationMeta },
	);

	bridge?.emitProcessEvent?.(projectId, "process:stderr", {
		taskId,
		chunk: errorMsg,
		projectName: projectId,
	});
	bridge?.emitProcessEvent?.(projectId, "process:exit", {
		taskId,
		stageId: stage?.id,
		exitCode: typeof error?.code === "number" ? error.code : 1,
		status: "failed",
		error: errorMsg,
		projectName: projectId,
	});

	if (!effectiveSkipFailback && !wasInterrupted) {
		const fallbackTarget =
			fallbackStageId || stage?.fallbackStageId || stage?.failback;
		bridge?.emitProcessEvent?.(projectId, "stage:failback", {
			taskId,
			fromStageId: stage?.id,
			targetStageId: fallbackTarget || task.currentStageId,
			error: errorMsg,
			projectName: projectId,
			classification: classificationMeta,
			...(compactionHintEffective ? { compactionHint: true } : {}),
		});

		taskStore.failbackStage(projectId, taskId, stages, fallbackTarget, bridge, cwd);

		task.failureReason = errorMsg;
		task.lastError = {
			message: errorMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			stageType,
			stderr: stderrText,
			stdout: stdoutText,
			...(failureKind ? { failureKind } : {}),
			...(gitDiagnosticsOf(error) ? { gitDiagnostics: gitDiagnosticsOf(error) } : {}),
			classification: classificationMeta,
			...(compactionHintEffective ? { compactionHint: true } : {}),
			timestamp: new Date().toISOString(),
		};
	}

	const autoIteration =
		effectiveSkipFailback || wasInterrupted
			? null
			: beginAutoIteration(task, stage, errorMsg, failureProject);
	if (autoIteration) {
		// Early warning before the budget runs out: edge-triggered per
		// threshold, detached so a dead sink never slows the retry.
		void maybeEmitFailbackWarning(bridge, {
			projectId,
			task,
			stage,
			attempt: task.autoIterationCount,
			maxAttempts: autoIteration.maxAttempts,
			error: errorMsg,
		});
		taskStore._saveTaskMarkdown(cwd, task);
		const targetStage = stages.find(
			(s) =>
				String(s.id) === String(task.currentStageId) ||
				(s.name &&
					String(s.name).toLowerCase() ===
						String(task.currentStageId).toLowerCase()),
		);
		// The re-run shape was already settled on the task flags by
		// beginAutoIteration (same-stage in-place retry vs cross-stage auto
		// iteration): read it back here so the operator-visible event and log
		// use the same verdict as every UI surface, instead of calling every
		// automatic re-run a "retry". The event name stays `stage:auto_retry`
		// (consumers filter on it); the `sameStage` field carries the shape.
		const movedStages = task.autoIterating === true;
		bridge?.emitProcessEvent?.(projectId, "stage:auto_retry", {
			taskId,
			fromStageId: stage?.id,
			targetStageId: task.currentStageId,
			targetStageName: targetStage?.name || task.currentStageId,
			sameStage: !movedStages,
			attempt: task.autoIterationCount,
			maxAttempts: autoIteration.maxAttempts,
			error: errorMsg,
			projectName: projectId,
		});
		bridge?.emitSystemLog?.(
			projectId,
			movedStages
				? `[AUTO] Stage '${stage?.name || stage?.id}' failed on task #${task.id?.slice(0, 4)}; continuing at '${targetStage?.name || task.currentStageId}' (attempt ${task.autoIterationCount}/${autoIteration.maxAttempts}): ${errorMsg}`
				: `[AUTO] Stage '${stage?.name || stage?.id}' failed on task #${task.id?.slice(0, 4)}; retrying same stage '${targetStage?.name || task.currentStageId}' (attempt ${task.autoIterationCount}/${autoIteration.maxAttempts}): ${errorMsg}`,
			{ taskId, stageId: stage?.id, error: errorMsg },
		);
		if (taskStore.schedulerRunning) {
			setTimeout(() => {
				taskStore.scheduleTick().catch(() => {});
			}, 2000);
		}
		return {
			task,
			stageType,
			status: "retrying",
			error: errorMsg,
			failureReason: errorMsg,
			autoIteration: true,
			attempt: task.autoIterationCount,
			maxAttempts: autoIteration.maxAttempts,
			exitCode: typeof error?.code === "number" ? error.code : 1,
		};
	}

	const parkedFrom = wasInterrupted ? "interrupted" : task.status;
	if (!wasInterrupted) {
		task.status = "failed";
	}
	// A parked task is never a retry: when the failback was skipped
	// (unrecoverable/ interrupted) moveToStage never ran, so a stale
	// autoRetrying flag from an earlier transient retry could otherwise
	// linger here and make a FAILED task read as RETRYING. Clear both
	// re-run flags on every park so the label can only mean an in-place
	// retry that is actually about to happen.
	task.autoRetrying = false;
	task.autoIterating = false;
	taskStore._saveTaskMarkdown(cwd, task);

	// Human-intervention push: the task is parked and auto-recovery cannot
	// proceed (unrecoverable error, exhausted budget, or failback-skipped
	// land). Normal CI failures that fail back, deliberate rejections, and
	// human-checkpoint parks stay silent. Best-effort: never breaks routing.
	if (!wasInterrupted) {
		// User-facing error toast: the task parked without automatic
		// recovery, so this genuinely needs the operator. Skipped for
		// auto-retries and failback continuations (those recover on their
		// own and surface their own retry/failback events).
		bridge?.emitNotification?.(projectId, {
			type: "error",
			title: `Stage "${stage?.name || stage?.id}" Failed`,
			message: errorMsg,
			taskId,
			stageId: stage?.id,
		});
		const pushReason = resolveStageErrorPushReason({
			task,
			parkedFrom,
			stage,
			error,
			failureKind,
			failureProject,
			skipFailback: effectiveSkipFailback,
		});
		if (pushReason) {
			fireStageErrorPush(taskStore, {
				projectId,
				taskId,
				stage,
				error: errorMsg,
				reason: pushReason,
			});
		}
		// Outbound alert: an unscheduled park is `failed`/`critical`, never
		// confused with a scheduled `waiting_human` checkpoint. Detached so
		// an unreachable sink settles the task identically. The WP2
		// classification (already computed for the timeline) supplies the
		// precise signal, so the payload and the audit trail cannot disagree.
		const parkedKind = classificationMeta.kind;
		const parkedSeverity = resolveAlertSeverity("failed", parkedKind);
		// Project-blocker dedupe (C3): one red shared gate parks N tasks, but
		// only the FIRST park per gate@sha emits the project-level alert —
		// later parks record the same reason in history/timeline without
		// re-alerting. Best-effort and in-memory (a restart may re-alert
		// once); never breaks routing.
		let suppressParkedAlert = false;
		try {
			suppressParkedAlert = shouldSuppressProjectBlockerAlert(
				taskStore,
				error?.projectBlocker?.key,
				{ taskId, projectId },
			);
		} catch {
			suppressParkedAlert = false;
		}
		if (parkedSeverity && !suppressParkedAlert) {
			void emitAlert(bridge, {
				event: "task.failed",
				severity: parkedSeverity,
				projectId,
				taskId,
				stage: { id: stage?.id, name: stage?.name || stage?.id, type: stageType },
				kind: parkedKind,
				signal: classificationMeta.signal,
				message: errorMsg,
				excerpt: excerptLog(
					[errorMsg, stderrText, stdoutText].filter(Boolean).join("\n"),
				),
				attemptCounts: {
					transient: task.infraRetryCount || 0,
					autoIteration: task.autoIterationCount || 0,
				},
				...parkedAlertStructuredFields(task, error),
			});
		}
	}

	return {
		task,
		stageType,
		status: task.status,
		error: errorMsg,
		failureReason: errorMsg,
		exitCode: typeof error?.code === "number" ? error.code : 1,
	};
}

import {
	config,
} from "../../../config.js";
import {
	_appendProcessLog,
} from "../../../watch/index.js";
import {
	emitAlert,
	resolveAlertSeverity,
	resolveErrorClassification,
} from "../../../observability/alerts.js";
import {
	isTerminalTaskStatus,
	stageElapsedSeconds,
} from "../../stagePolicy.js";
import {
	consumeStallHandled,
} from "../../stageHeartbeat.js";
import {
	isTripped,
} from "../../circuitBreaker.js";
import {
	recordCircuitFailure,
} from "../../circuitSensors.js";
import {
	buildTimelineAttribution,
} from "../../runAttribution.js";
import {
	classificationMetaOf,
	computeRetryDelay,
	excerptLog,
	fireStageErrorPush,
	resolveFailureProject,
	resolveRetryable,
	resolveTransientBudget,
} from '../resolvers/index.js';
import { settleOperatorAbort } from './settleOperatorAbort.js';
import { deferForCircuitTrip } from './deferForCircuitTrip.js';
import { handleStageFailure } from './handleStageFailure.js';
import { recordTransientAttemptReport } from './recordTransientAttemptReport.js';

/***
 * MARK: handleTransientFailure
 * @description Handles transient infrastructure failures by retrying the SAME stage instead of failback routing.
 * @param {Object} taskStore - TaskStore instance.
 * @param {string} projectId
 * @param {string} taskId
 * @param {Object} stage
 * @param {Error|string} error
 * @param {Object} [opts]
 * @param {Object} [opts.bridge]
 * @param {string} [opts.projectCwd]
 * @param {string} [opts.harnessId] - Harness that ran the failed attempt (reliability attribution; a FAILED report is recorded only when present with the infrastructure kind).
 * @param {string} [opts.failureKind] - Runner outcome kind (must be "infrastructure" for the attempt report).
 * @param {string} [opts.aliasName] - Model alias the failed attempt resolved through (per-alias reliability attribution).
 * @param {string} [opts.modelRef] - Concrete model the alias target dispatched.
 * @param {number} [opts.targetIndex] - Weighted-target index of the alias pick (informational).
 * @param {string} [opts.runnerId] - Runner that ran the failed attempt (recorded on both the Retrying/exhausted timeline rows and the attempt report when present, so a struggling Runner can be spotted per stage or task type later; absent for embedded runs).
 * @param {Object} [opts.retryDelay] - Per-call delay overrides (`baseMs`, `capMs`, `jitterMs`, `strategy`; WP10 fault-injection seam).
 * @param {Function} [opts.retryRand] - Injectable uniform [0,1) source for jitter (deterministic tests; default `Math.random`).
 * @returns {Object} Retry or parked-failure result.
  * @example handleTransientFailure(store, "p1", "t1", stage, err, {}) => { status: "in_stage", … }
 ***/
export function handleTransientFailure(
	taskStore,
	projectId,
	taskId,
	stage,
	error,
	opts = {},
) {
	const {
		bridge = taskStore.eventBridge,
		projectCwd,
		harnessId,
		failureKind,
		aliasName,
		modelRef,
		targetIndex,
		runnerId,
		retryDelay,
		retryRand,
	} = opts;
	const failureProject = resolveFailureProject(taskStore, projectId, opts);
	const task = taskStore.getTask(projectId, taskId);
	if (!task) return null;
	// WP6 watchdog de-duplication: see `handleStageFailure`. The watchdog's own
	// routing runs BEFORE the marker is set, so this only suppresses the
	// duplicate emitted by the terminated in-flight run.
	if (consumeStallHandled(taskStore, taskId)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: task.status,
			message:
				"Stage stall already handled by the watchdog; duplicate transient routing suppressed",
		};
	}
	const { classification, classificationMeta } = classificationMetaOf(error);
	// A transient error settling after the task finished must not flip it
	// back to in_stage for another retry.
	if (isTerminalTaskStatus(task.status)) {
		return {
			task,
			stageType: stage?.type || "agent",
			status: task.status,
			message: `Task is already ${task.status}; transient failure ignored`,
		};
	}
	// Same for a paused task: no retry flip, no budget consumed.
	if (String(task.status).toLowerCase() === "paused") {
		return {
			task,
			stageType: stage?.type || "agent",
			status: "paused",
			message: "Task is paused; transient failure does not retry",
		};
	}

	// An operator-initiated abort carries no actionable failure: settle
	// quietly without retry or budget, whatever the status.
	if (classification.kind === "operator-abort") {
		return settleOperatorAbort(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
		});
	}

	// Tier-5 gate: record the infrastructure failure against the trip sensors
	// (this call may itself trip the engine), then quiet-defer instead of
	// incrementing `infraRetryCount` or flipping the task back to `in_stage`.
	recordCircuitFailure(taskStore, { taskId, error, failureKind });
	if (isTripped(taskStore)) {
		const deferral = deferForCircuitTrip(taskStore, projectId, taskId, stage, error, {
			bridge,
			projectCwd,
			failureKind,
		});
		if (deferral && !deferral.continueNormalHandling) return deferral;
	}

	// A task parked as interrupted by an engine stop keeps that state so
	// resume/retry starts clean: record the failure for feedback but never
	// flip it back to in_stage or spend retry budget by itself.
	if (String(task.status).toLowerCase() === "interrupted") {
		const interruptedMsg =
			typeof error === "string" ? error : error?.message || "Transient infrastructure failure";
		const interruptedCwd = taskStore._resolveProjectCwd(projectId, projectCwd);
		task.failureReason = interruptedMsg;
		task.lastError = {
			message: interruptedMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			stageType: stage?.type || "agent",
			classification: classificationMeta,
			timestamp: new Date().toISOString(),
		};
		task.autoRetrying = false;
		task.autoIterating = false;
		if (!Array.isArray(task.history)) {
			task.history = [];
		}
		task.history.push({
			timestamp: new Date().toISOString(),
			action: `Transient infrastructure error in '${stage?.name || stage?.id || "unknown"}' while interrupted: ${interruptedMsg} — awaiting resume/retry`,
		});
		taskStore._saveTaskMarkdown(interruptedCwd, task);
		return {
			task,
			stageType: stage?.type || "agent",
			status: "interrupted",
			message: "Task is interrupted; transient failure does not retry",
		};
	}

	const errorMsg =
		typeof error === "string"
			? error
			: error?.message || "Transient infrastructure failure";
	const cwd = taskStore._resolveProjectCwd(projectId, projectCwd);
	const stageType = stage?.type || "agent";
	const stageLabel = stage?.name || stage?.id || "unknown";
	const { maxAttempts, source: budgetSource } = resolveTransientBudget(stage, failureProject);
	task.infraRetryCount = (task.infraRetryCount || 0) + 1;
	const attempt = task.infraRetryCount;
	// WP3 retryable signal: the WP2 signal when infrastructure-classified,
	// otherwise the matched harness-blip signal (deny-listed errors never
	// reach this handler via resolveRetryable, but resolve it anyway so the
	// ladder always names what was matched).
	const retrySignal = resolveRetryable(error).signal || classificationMeta.signal;
	const budgetNote = `budget ${maxAttempts} from ${budgetSource === "stage" ? "stage.maxTransientRetries" : budgetSource === "project" ? "project.maxTransientRetries" : "global config"}`;
	if (!Array.isArray(task.transientRetryLadder)) {
		task.transientRetryLadder = [];
	}

	if (attempt > maxAttempts) {
		const ladderLines = task.transientRetryLadder.map(
			(entry) => `attempt ${entry.attempt}/${maxAttempts}: ${entry.delayMs}ms [${entry.signal}] ${entry.error}`,
		);
		const ladderText = ladderLines.length > 0 ? ` Retry ladder: ${ladderLines.join(" | ")}.` : "";
		task.failureReason = errorMsg;
		task.lastError = {
			message: errorMsg,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			stageType,
			classification: classificationMeta,
			transientBudget: { maxAttempts, source: budgetSource },
			retryLadder: [...task.transientRetryLadder],
			timestamp: new Date().toISOString(),
		};
		task.status = "failed";
		task.autoRetrying = false;
		task.autoIterating = false;
		if (!Array.isArray(task.history)) {
			task.history = [];
		}
		task.history.push({
			timestamp: new Date().toISOString(),
			action: `Stage '${stageLabel}' parked after ${maxAttempts} transient-failure retries (${budgetNote}): ${errorMsg}.${ladderText}`,
		});
		_appendProcessLog(
			task,
			`[ERROR] Stage '${stageLabel}' still unreachable after ${maxAttempts} retries (${budgetNote}); parked for human intervention. Last error: ${errorMsg}.${ladderText}`,
		);
		taskStore._recordTimelineWithDiffStat?.(
			task,
			{
				stage: stage?.name || stage?.id || task.currentStageId,
				status: "Failed",
				duration: stageElapsedSeconds(task) === undefined ? "--" : `${stageElapsedSeconds(task)}s`,
				timestamp: new Date().toISOString(),
				reason: `Transient retries exhausted (${attempt - 1}/${maxAttempts}, ${budgetNote}): ${errorMsg}.${ladderText}`,
				stageId: stage?.id,
				stageName: stage?.name || stage?.id,
				classification: classificationMeta,
				signal: retrySignal,
				maxAttempts,
				budgetSource,
				retryLadder: [...task.transientRetryLadder],
				...(buildTimelineAttribution({
					harnessId,
					aliasName,
					modelRef,
					targetIndex,
					runnerId,
				}) || {}),
			},
			cwd,
		);
		recordTransientAttemptReport(
			taskStore,
			projectId,
			taskId,
			stage,
			errorMsg,
			`Transient infrastructure error persisted after ${maxAttempts} retries (${budgetNote}): ${errorMsg}.${ladderText}`,
			cwd,
			harnessId,
			failureKind,
			{ aliasName, modelRef, targetIndex, runnerId },
		);
		taskStore._saveTaskMarkdown(cwd, task);
		// Transient budget exhausted: the stage is parked and cannot
		// auto-recover — this always needs a human. Best-effort hook.
		fireStageErrorPush(taskStore, {
			projectId,
			taskId,
			stage,
			error: errorMsg,
			reason: "transient_retries_exhausted",
		});
		// Outbound alert: persistent infrastructure exhaustion parks the task
		// for a human (`failed`/`critical`). Detached: a dead sink parks
		// the task exactly the same way. The kind is classified (not
		// hardcoded) so an operator abort that reaches this path settles
		// quietly instead of paging.
		const exhausted = resolveErrorClassification(error);
		const exhaustedSeverity = resolveAlertSeverity("failed", exhausted.kind);
		if (exhaustedSeverity) {
			void emitAlert(bridge, {
				event: "task.failed",
				severity: exhaustedSeverity,
				projectId,
				taskId,
				stage: { id: stage?.id, name: stage?.name || stage?.id, type: stageType },
				kind: exhausted.kind,
				signal: exhausted.signal,
				message: errorMsg,
				excerpt: excerptLog(errorMsg),
				attemptCounts: { attempt, maxAttempts },
			});
		}
		bridge?.emitNotification?.(projectId, {
			type: "error",
			title: `Stage "${stageLabel}" Unreachable`,
			message: `Gave up after ${maxAttempts} retries: ${errorMsg}`,
			taskId,
			stageId: stage?.id,
		});
		bridge?.emitSystemLog?.(
			projectId,
			`[ERROR] Stage '${stageLabel}' failed on task #${task.id?.slice(0, 4)} with a persistent infrastructure error after ${maxAttempts} retries; parked: ${errorMsg}`,
			{ taskId, stageId: stage?.id, error: errorMsg },
		);
		bridge?.emitProcessEvent?.(projectId, "process:exit", {
			taskId,
			stageId: stage?.id,
			exitCode: typeof error?.code === "number" ? error.code : 1,
			status: "failed",
			error: errorMsg,
			projectName: projectId,
		});
		return {
			task,
			stageType,
			status: "failed",
			error: errorMsg,
			failureReason: errorMsg,
			retrySameStage: true,
			attempt,
			maxAttempts,
			budgetSource,
			signal: retrySignal,
			retryLadder: [...task.transientRetryLadder],
			exitCode: typeof error?.code === "number" ? error.code : 1,
		};
	}

	const nextDelayMs = computeRetryDelay(attempt, retryDelay, retryRand);
	task.transientRetryLadder.push({
		attempt,
		delayMs: nextDelayMs,
		signal: retrySignal,
		error: errorMsg,
		timestamp: new Date().toISOString(),
	});
	task.failureReason = null;
	task.lastError = null;
	task.status = "in_stage";
	task.autoRetrying = true;
	task.autoIterating = false;
	if (!Array.isArray(task.history)) {
		task.history = [];
	}
	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Transient infrastructure error in '${stageLabel}' (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
	});
	_appendProcessLog(
		task,
		`[WARN] Transient infrastructure error in stage '${stageLabel}' (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
	);
	taskStore._recordTimelineWithDiffStat?.(
		task,
		{
			stage: stage?.name || stage?.id || task.currentStageId,
			status: "Retrying",
			duration: stageElapsedSeconds(task) === undefined ? "--" : `${stageElapsedSeconds(task)}s`,
			timestamp: new Date().toISOString(),
			reason: `Transient error (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
			stageId: stage?.id,
			stageName: stage?.name || stage?.id,
			classification: classificationMeta,
			signal: retrySignal,
			attempt,
			maxAttempts,
			nextDelayMs,
			budgetSource,
			...(buildTimelineAttribution({
				harnessId,
				aliasName,
				modelRef,
				targetIndex,
				runnerId,
			}) || {}),
		},
		cwd,
	);
	recordTransientAttemptReport(
		taskStore,
		projectId,
		taskId,
		stage,
		errorMsg,
		`Transient infrastructure error (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg} — retrying same stage`,
		cwd,
		harnessId,
		failureKind,
		{ aliasName, modelRef, targetIndex, runnerId },
	);
	taskStore._saveTaskMarkdown(cwd, task);
	bridge?.emitProcessEvent?.(projectId, "stage:retry", {
		taskId,
		stageId: stage?.id,
		stageName: stage?.name || stage?.id,
		sameStage: true,
		transient: true,
		attempt,
		maxAttempts,
		nextDelayMs,
		signal: retrySignal,
		budgetSource,
		error: errorMsg,
		projectName: projectId,
		classification: classificationMeta,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[RETRY] Stage '${stageLabel}' hit a transient infrastructure error on task #${task.id?.slice(0, 4)}; retrying same stage (attempt ${attempt}/${maxAttempts}, ${budgetNote}, next delay ${nextDelayMs}ms, signal ${retrySignal}): ${errorMsg}`,
		{ taskId, stageId: stage?.id, error: errorMsg, classification: classificationMeta, nextDelayMs, signal: retrySignal, budgetSource },
	);
	if (taskStore.schedulerRunning) {
		setTimeout(() => {
			taskStore.scheduleTick().catch(() => {});
		}, nextDelayMs);
	}
	return {
		task,
		stageType,
		status: "retrying",
		error: errorMsg,
		failureReason: errorMsg,
		autoIteration: true,
		retrySameStage: true,
		attempt,
		maxAttempts,
		nextDelayMs,
		budgetSource,
		signal: retrySignal,
		exitCode: typeof error?.code === "number" ? error.code : 1,
	};
}

import {
