		// Nothing finalized — restore the pre-merge state, do not leave a
		// half-resolved squash state for later stages to trip on.
		try {
			await abortSquashMerge(cwd);
		} catch {
			// Best effort.
		}
		return false;
	}
	const healed = healCommit?.hash ? ` (${healCommit.hash})` : "";
